import{_ as i,a0 as s,w as l,s as m,ao as r,I as o,a1 as a,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二） | LCTT x X-CMD","titleTemplate":false,"description":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二） | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二） | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/30 Things to Do After Minimal RHEL or CentOS 7 Installation--2","title":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二）","tag":"201504","desc":""},"relativePath":"201504/30 Things to Do After Minimal RHEL or CentOS 7 Installation--2.md","filePath":"[post].md"}'),d={name:"201504/30 Things to Do After Minimal RHEL or CentOS 7 Installation--2.md"};function c(h,t,S,w,u,C){const p=s("Link");return l(),m("div",null,[t[18]||(t[18]=r(`<h1 id="安裝完最小化-rhel-centos-7-後需要做的-30-件事情-二" tabindex="-1">安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二） <a class="header-anchor" href="#安裝完最小化-rhel-centos-7-後需要做的-30-件事情-二" aria-label="Permalink to “安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（二）”">​</a></h1><h3 id="_7-安裝-php" tabindex="-1">7. 安裝 PHP <a class="header-anchor" href="#_7-安裝-php" aria-label="Permalink to “7. 安裝 PHP”">​</a></h3><p>PHP 是用於 web 基礎服務的服務器端腳本語言。它也經常被用作通用編程語言。在最小化安裝的 CentOS 中安裝 PHP：</p><pre><code># yum install php
</code></pre><p>安裝完 php 之後，確認重啓 Apache 服務以便在 Web 瀏覽器中渲染 PHP。</p><pre><code># systemctl restart httpd.service
</code></pre><p>下一步，通過在 Apache 文檔根目錄下創建下面的 php 腳本驗證 PHP。</p><pre><code># echo -e &quot;&lt;?php\\nphpinfo();\\n?&gt;&quot;  &gt; /var/www/html/phpinfo.php
</code></pre><p>現在在 Linux 命令列中查看我們剛才創建的 PHP 文件(phpinfo.php)。</p><pre><code># php /var/www/html/phpinfo.php
或者
# links http://127.0.0.1/phpinfo.php
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Verify-PHP.jpeg" alt="驗證 PHP"></p><p><em>驗證 PHP</em></p><h3 id="_8-安裝-mariadb-資料庫" tabindex="-1">8. 安裝 MariaDB 資料庫 <a class="header-anchor" href="#_8-安裝-mariadb-資料庫" aria-label="Permalink to “8. 安裝 MariaDB 資料庫”">​</a></h3><p>MariaDB 是 MySQL 的一個分支。RHEL 以及它的衍生版已經從 MySQL 遷移到 MariaDB。這是一個主流的資料庫管理系統，也是一個你必須擁有的工具。不管你在配置怎樣的服務器，或遲或早你都會需要它。在最小化安裝的 CentOS 上安裝 MariaDB，如下所示：</p><pre><code># yum install mariadb-server mariadb
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-MariaDB-Database.jpeg" alt="安裝 MariaDB 資料庫"></p><p><em>安裝 MariaDB 資料庫</em></p><p>啓動 MariaDB 並配置它開機時自動啓動。</p><pre><code># systemctl start mariadb.service
# systemctl enable mariadb.service
</code></pre><p>允許 mysql(mariadb) 服務通過防火牆（LCTT 譯註：如果你的 MariaDB 只用在本機，則務必不要設置防火牆允許通過，使用 UNIX Socket 連接你的資料庫；如果需要在別的服務器上連接資料庫，則儘量使用內部網絡，而不要將資料庫服務暴露在公開的互聯網上。）</p><pre><code># firewall-cmd –add-service=mysql
</code></pre><p>現在是時候確保 MariaDB 服務器安全了（LCTT 譯註：這個步驟主要是設置 mysql 管理密碼）。</p><pre><code># /usr/bin/mysql_secure_installation
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Secure-MariaDB.jpeg" alt="保護 MariaDB 資料庫"></p><p><em>保護 MariaDB 資料庫</em></p><p>請閲讀:</p>`,26)),o("ul",null,[o("li",null,[a(p,{href:"http://www.tecmint.com/install-lamp-in-centos-7/"},{default:n(()=>[...t[0]||(t[0]=[e("在 CentOS 7.0 上安裝 LAMP (Linux, Apache, MariaDB, PHP/PhpMyAdmin)",-1)])]),_:1})]),o("li",null,[a(p,{href:"http://www.tecmint.com/apache-virtual-hosting-in-centos/"},{default:n(()=>[...t[1]||(t[1]=[e("在 CentOS 7.0 上創建 Apache 虛擬主機",-1)])]),_:1})])]),t[19]||(t[19]=r(`<h3 id="_9-安裝和配置-ssh-服務器" tabindex="-1">9. 安裝和配置 SSH 服務器 <a class="header-anchor" href="#_9-安裝和配置-ssh-服務器" aria-label="Permalink to “9. 安裝和配置 SSH 服務器”">​</a></h3><p>SSH 即 Secure Shell，是 Linux 遠程管理的默認協議。 SSH 是隨最小化 CentOS 服務器中安裝運行的最重要的軟件之一。</p><p>檢查當前已安裝的 SSH 版本。</p><pre><code># SSH -V
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-SSH-Version.jpeg" alt="檢查 SSH 版本"></p><p><em>檢查 SSH 版本</em></p><p>使用更安全的 SSH 協議，而不是默認的協議，並更改端口號進一步加強安全。編輯 SSH 的配置文件 ‘/etc/ssh/ssh_config’。</p><p>去掉下面行的註釋或者從協議行中刪除 1，然後行看起來像這樣（LCTT 譯註： SSH v1 是過期廢棄的不安全協議）：</p><pre><code># Protocol 2,1 (原來)
Protocol 2 (現在)
</code></pre><p>這個改變強制 SSH 使用 協議 2，它被認為比協議 1 更安全，同時也確保在配置中更改端口號 22 為其它。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Secure-SSH.jpeg" alt="保護 SSH 登錄"></p><p><em>保護 SSH 登錄</em></p><p>取消 SSH 中的‘root login’， 只允許通過普通用户賬號登錄後才能使用 su 切換到 root，以進一步加強安全。請打開並編輯配置文件 ‘/etc/ssh/sshd_config’ 並更改 PermitRootLogin yes 為 PermitRootLogin no。</p><pre><code># PermitRootLogin yes (原來) 
PermitRootLogin no (現在)
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Disable-SSH-Root-Login.jpeg" alt="取消 SSH Root 登錄"></p><p><em>取消 SSH Root 直接登錄</em></p><p>最後，重啓 SSH 服務啓用更改。</p><pre><code># systemctl restart sshd.service
</code></pre><p>請查看:</p>`,19)),o("ul",null,[o("li",null,[a(p,{href:"http://www.tecmint.com/5-best-practices-to-secure-and-protect-ssh-server/"},{default:n(()=>[...t[2]||(t[2]=[e("加密和保護 SSH 服務器的 5 個最佳實踐",-1)])]),_:1})]),o("li",null,[a(p,{href:"http://www.tecmint.com/ssh-passwordless-login-using-ssh-keygen-in-5-easy-steps/"},{default:n(()=>[...t[3]||(t[3]=[e("5 個簡單步驟實現使用 SSH Keygen 無密碼登錄 SSH",-1)])]),_:1})]),o("li",null,[a(p,{href:"http://www.tecmint.com/ssh-passwordless-login-with-putty/"},{default:n(()=>[...t[4]||(t[4]=[e("在 PuTTY 中實現 “無密碼 SSH 密鑰驗證”",-1)])]),_:1})])]),t[20]||(t[20]=r(`<h3 id="_10-安裝-gcc-gnu-編譯器集" tabindex="-1">10. 安裝 GCC (GNU 編譯器集) <a class="header-anchor" href="#_10-安裝-gcc-gnu-編譯器集" aria-label="Permalink to “10. 安裝 GCC (GNU 編譯器集)”">​</a></h3><p>GCC 即 GNU 編譯器集，是一個 GNU 項目開發的支持多種編程語言的編譯系統（LCTT 譯註：在你需要自己編譯構建軟件時需要它）。在最小化安裝的 CentOS 沒有默認安裝。運行下面的命令安裝 gcc 編譯器。</p><pre><code># yum install gcc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-GCC-in-CentOS.jpeg" alt="在 CentOS 上安裝 GCC"></p><p><em>在 CentOS 上安裝 GCC</em></p><p>檢查安裝的 gcc 版本。</p><pre><code># gcc --version
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-GCC-Version.jpeg" alt="檢查 GCC 版本"></p><p><em>檢查 GCC 版本</em></p><h3 id="_11-安裝-java" tabindex="-1">11. 安裝 Java <a class="header-anchor" href="#_11-安裝-java" aria-label="Permalink to “11. 安裝 Java”">​</a></h3><p>Java是一種通用的基於類的，面向對象的編程語言。在最小化 CentOS 服務器中沒有默認安裝（LCTT 譯註：如果你沒有任何 Java 應用，可以不用裝它）。按照下面命令從庫中安裝 Java。</p><pre><code># yum install java
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-java.jpeg" alt="在 CentOS 上安裝 Java"></p><p><em>安裝 Java</em></p><p>檢查安裝的 Java 版本。</p><pre><code># java -version
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-Java-Version.jpeg" alt="檢查 Java 版本"></p><p><em>檢查 Java 版本</em></p><hr>`,19)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),a(p,{href:"http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/2/"},{default:n(()=>[...t[5]||(t[5]=[e("http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/2/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),a(p,{href:"http://www.tecmint.com/author/avishek/"},{default:n(()=>[...t[7]||(t[7]=[e("Avishek Kumar",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),a(p,{href:"https://github.com/ictlyh"},{default:n(()=>[...t[8]||(t[8]=[e("ictlyh",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),a(p,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),a(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),a(p,{href:"http://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const H=i(d,[["render",c]]);export{T as __pageData,H as default};
